{
  "watches": [
    {
      "name": "todo-list-display",
      "targets": [
        "features/todo-management.feature:No todos hides main and footer sections",
        "features/todo-management.feature:Create a new todo by pressing Enter",
        "features/todo-management.feature:Trimming whitespace from new todo title",
        "features/todo-management.feature:Empty todo is not created",
        "features/todo-management.feature:Show the active todo count",
        "features/todo-management.feature:Pluralize item count correctly"
      ]
    },
    {
      "name": "todo-completion",
      "targets": [
        "features/todo-completion.feature:Toggle a single todo as complete",
        "features/todo-completion.feature:Mark all todos as complete",
        "features/todo-completion.feature:Clear completed button is hidden when no completed todos",
        "features/todo-completion.feature:Clear completed button removes completed todos",
        "features/todo-completion.feature:Toggle-all reflects individual completion state"
      ]
    },
    {
      "name": "todo-editing",
      "targets": [
        "features/todo-editing.feature:Double-clicking a todo label activates editing mode",
        "features/todo-editing.feature:Save edit by pressing Enter",
        "features/todo-editing.feature:Save edit by blurring the input",
        "features/todo-editing.feature:Cancel edit by pressing Escape",
        "features/todo-editing.feature:Empty title destroys the todo on save"
      ]
    },
    {
      "name": "routing-and-filtering",
      "targets": [
        "features/routing.feature:Default route shows all todos",
        "features/routing.feature:Active route shows only active todos",
        "features/routing.feature:Completed route shows only completed todos",
        "features/routing.feature:Selected filter class toggles with route change",
        "features/routing.feature:Completing a todo in a filtered view hides it"
      ]
    },
    {
      "name": "persistence",
      "targets": [
        "features/persistence.feature:Todos are persisted to localStorage",
        "features/persistence.feature:Todos are restored from localStorage on load",
        "features/persistence.feature:Completion state is persisted"
      ]
    }
  ]
}
